/**
 * The notice's artwork: one flat illustration split into the layers the notice
 * animates — the scene without its whale, the deep wave band that passes in
 * front of the whale, the spray, and the whale itself. The layers are user
 * artwork; each is inlined as a WebP data URL so the client bundle needs no
 * separate asset request, and their geometry is percent of the scene box so
 * the layers line up exactly as drawn.
 */

/** Scene box the layers are positioned inside, in CSS pixels. */
export const ART_SCENE = { width: 420, height: 315 } as const

/** One positioned layer: the image plus its box inside the scene. */
export interface ArtLayer {
  /** Layer image as a data URL. */
  readonly src: string
  /** Left edge as a percent of the scene width. */
  readonly left: number
  /** Top edge as a percent of the scene height. */
  readonly top: number
  /** Width as a percent of the scene width. */
  readonly width: number
}

